package com.vibeguard.samples.lockouts; import java.util.*; import java.util.concurrent.ConcurrentHashMap; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; /** Tracks failed attempts and locks accounts after five failures. */ @RestController @RequestMapping("/internal/lockouts") public class LockoutController { private final Map<String,Integer> failures=new ConcurrentHashMap<>(); @Value("${LOCKOUT_EVENTS_KEY:}") private String key; @PostMapping("/{accountId}/failures") public ResponseEntity<Status> failure(@RequestHeader("X-Lockout-Events-Key") String supplied,@PathVariable String accountId){if(!key.equals(supplied))return ResponseEntity.status(401).build();int count=failures.merge(accountId,1,Integer::sum);return ResponseEntity.ok(new Status(accountId,count,count>=5));}@GetMapping("/{accountId}") public ResponseEntity<Status> status(@RequestHeader("X-Lockout-Events-Key") String supplied,@PathVariable String accountId){if(!key.equals(supplied))return ResponseEntity.status(401).build();int count=failures.getOrDefault(accountId,0);return ResponseEntity.ok(new Status(accountId,count,count>=5));}@DeleteMapping("/{accountId}") public ResponseEntity<Void> reset(@RequestHeader("X-Lockout-Events-Key") String supplied,@PathVariable String accountId){if(!key.equals(supplied))return ResponseEntity.status(401).build();failures.remove(accountId);return ResponseEntity.noContent().build();}record Status(String accountId,int failedAttempts,boolean locked){} }
